
CREATE TABLE IF NOT EXISTS hr_accounts(id UUID PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password_hash TEXT NOT NULL DEFAULT '',active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS hr_grants(account_id UUID NOT NULL REFERENCES hr_accounts(id),scope TEXT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT false,PRIMARY KEY(account_id,scope));
CREATE TABLE IF NOT EXISTS hr_invites(token_hash TEXT PRIMARY KEY,account_id UUID NOT NULL REFERENCES hr_accounts(id),scope TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS hr_employees(id UUID PRIMARY KEY,scope TEXT NOT NULL,employee_code TEXT NOT NULL,data JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','FILLED','READY','SENT','ACCEPTED')),revision INTEGER NOT NULL DEFAULT 1,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(scope,employee_code));
CREATE INDEX IF NOT EXISTS hr_employees_scope_idx ON hr_employees(scope,status,updated_at);
CREATE TABLE IF NOT EXISTS hr_employee_links(id UUID PRIMARY KEY,employee_id UUID NOT NULL REFERENCES hr_employees(id),token_hash TEXT NOT NULL UNIQUE,code_hash TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS hr_sessions(token_hash TEXT PRIMARY KEY,account_id UUID REFERENCES hr_accounts(id),link_id UUID REFERENCES hr_employee_links(id),expires_at TIMESTAMPTZ NOT NULL,last_seen TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK((account_id IS NULL)<>(link_id IS NULL)));
CREATE TABLE IF NOT EXISTS hr_audit(id BIGSERIAL PRIMARY KEY,scope TEXT NOT NULL,actor TEXT NOT NULL,action TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS hr_audit_scope_idx ON hr_audit(scope,created_at DESC);
CREATE TABLE IF NOT EXISTS hr_attempts(key TEXT PRIMARY KEY,attempts INTEGER NOT NULL DEFAULT 1,window_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
